// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

// Module-level font loading guaranteed to be ready before frame 0
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();



export type ScrunchyPaperProps = Record<string, any>;

const ScrunchyPaper: React.FC<ScrunchyPaperProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 10,
  paperColor = "#f4eddf",
  textureIntensity = 0.9,
  stopMotionFps = 5,
  foldScale = 4.5,
  noiseFrequency = 0.012,
  headline = "MALLOY STUDIO\nSCRUNCHY PAPER",
  tags = ["LO-FI", "TEXTURE", "STOP-MOTION"],
  textColor = "#1c1b18",
  jitterAmount = 10,
}) => {
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  // Handle transparency constraint safely
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --------------------------------------------------------------------------
  // STOP-MOTION LOGIC
  // Calculate how many actual frames should pass before we update the "seed".
  // E.g., if fps = 30 and stopMotionFps = 5, we hold each visual state for 6 frames.
  // --------------------------------------------------------------------------
  const framesPerUpdate = Math.max(1, Math.floor(fps / stopMotionFps));
  
  // currentSeed increments by 1 only when framesPerUpdate frames have passed.
  const currentSeed = Math.floor(frame / framesPerUpdate);

  // --------------------------------------------------------------------------
  // FOREGROUND JITTER
  // Apply the same stop-motion timing to text displacement so it feels 
  // cohesively printed on the moving paper background.
  // --------------------------------------------------------------------------
  const jitterX = (random(`x-${currentSeed}`) * 2 - 1) * jitterAmount;
  const jitterY = (random(`y-${currentSeed}`) * 2 - 1) * jitterAmount;
  const jitterRot = (random(`rot-${currentSeed}`) * 2 - 1) * (jitterAmount * 0.15);

  // Responsive sizing constants
  const minDimension = Math.min(width, height);
  const fontSize = minDimension * 0.08;
  const tagFontSize = minDimension * 0.03;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* 
        BACKGROUND: SVG Filter Paper Texture 
        Uses unique IDs based on currentSeed to ensure Remotion captures
        the filter updates correctly on every simulated frame change.
      */}
      <svg
        width="100%"
        height="100%"
        style={{
          position: "absolute",
          opacity: textureIntensity,
          pointerEvents: "none",
          transition: "none",
        }}
      >
        <defs>
          <filter id={`paper-texture-${currentSeed}`}>
            {/* 1. Base fractal noise generation */}
            <feTurbulence
              type="fractalNoise"
              baseFrequency={noiseFrequency}
              numOctaves="5"
              seed={currentSeed}
              result="noise"
            />
            {/* 2. Convert flat noise into 3D shaded folds and creases */}
            <feDiffuseLighting
              in="noise"
              lightingColor="#ffffff"
              surfaceScale={foldScale}
              result="light"
            >
              <feDistantLight azimuth="45" elevation="65" />
            </feDiffuseLighting>
            {/* 3. Blend lighting onto the colored rect below */}
            <feBlend mode="multiply" in="SourceGraphic" in2="light" />
          </filter>
        </defs>

        <rect
          width="100%"
          height="100%"
          fill={paperColor}
          filter={`url(#paper-texture-${currentSeed})`}
          style={{ transition: "none" }}
        />
      </svg>

      {/* 
        FOREGROUND: Content overlay 
        Jitters in sync with the paper texture updates. 
      */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          padding: "10%",
          transform: `translate(${jitterX}px, ${jitterY}px) rotate(${jitterRot}deg)`,
          transition: "none", 
        }}
      >
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: `${minDimension * 0.05}px`,
            width: "100%",
            transition: "none",
          }}
        >
          {/* Headline */}
          <h1
            style={{
              fontFamily: spaceGroteskFamily,
              fontSize,
              fontWeight: 800,
              color: textColor,
              textAlign: "center",
              whiteSpace: "pre-wrap",
              lineHeight: 1.05,
              letterSpacing: "-0.03em",
              margin: 0,
              // Blend text into the paper for an "inked" look
              mixBlendMode: "multiply",
              transition: "none",
            }}
          >
            {headline}
          </h1>

          {/* Tags List */}
          {tags.length > 0 && (
            <div
              style={{
                display: "flex",
                flexWrap: "wrap",
                gap: `${minDimension * 0.02}px`,
                justifyContent: "center",
                marginTop: `${minDimension * 0.02}px`,
                mixBlendMode: "multiply",
                transition: "none",
              }}
            >
              {tags.map((tag, idx) => {
                // Individual tag slight misalignments for analog feel
                const tagJitterRot = (random(`tag-rot-${currentSeed}-${idx}`) * 2 - 1) * 3;
                
                return (
                  <div
                    key={idx}
                    style={{
                      fontFamily: spaceGroteskFamily,
                      fontSize: tagFontSize,
                      fontWeight: 600,
                      color: textColor,
                      border: `${Math.max(2, minDimension * 0.003)}px solid ${textColor}`,
                      padding: `${minDimension * 0.015}px ${minDimension * 0.03}px`,
                      borderRadius: `${minDimension * 0.1}px`,
                      transform: `rotate(${tagJitterRot}deg)`,
                      transition: "none",
                    }}
                  >
                    {tag}
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default ScrunchyPaper;